<script setup>
/**
 * Daftar Master Karyawan (read-only).
 *
 * Kolom kartu mengikuti field yang ditandai `in_list_view` di doctype — sama
 * dengan yang dipakai list view desk — jadi kalau HR mengubah field mana yang
 * tampil di list, app ikut berubah tanpa ubah kode. Nama, foto, dan status
 * dipakai sebagai kerangka kartu dan selalu diambil.
 *
 * Akses murni mengikuti permission doctype: query lewat `frappe.client.get_list`
 * tanpa ignore_permissions, sehingga user hanya melihat yang memang boleh
 * dilihatnya.
 */
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'

const DOCTYPE = 'Master Karyawan'
const router = useRouter()
const listPersistence = useListPersistence('MasterKaryawan')

function goToDetail(name) {
	router.push({ name: 'MasterKaryawanDetail', params: { name } })
}

// Kerangka kartu — selalu diambil, di luar field in_list_view dari meta.
const BASE_FIELDS = ['name', 'employee_name', 'status', 'image']
// Field yang tidak layak jadi baris subtitle walau in_list_view (sudah jadi
// bagian kerangka kartu, atau terlalu sensitif untuk dipajang di daftar).
const SUBTITLE_SKIP = ['name', 'employee_name', 'image', 'status', 'first_name']

const metaListFields = ref([])
const statusOptions = ref([''])

const listFields = computed(() => [
	...new Set([...BASE_FIELDS, ...metaListFields.value.map((f) => f.fieldname)]),
])

function initials(v) {
	return String(v || '?')
		.trim()
		.split(/\s+/)
		.slice(0, 2)
		.map((w) => w[0])
		.join('')
		.toUpperCase()
}

const STATUS_PILL = {
	Active: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	Inactive: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	Suspended: 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	Left: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
function statusPill(s) {
	return STATUS_PILL[s] || 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
}

function formatDate(v) {
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
// Subtitle = gabungan field in_list_view yang terisi, dipisah titik tengah.
function subtitle(row) {
	const parts = metaListFields.value
		.filter((f) => !SUBTITLE_SKIP.includes(f.fieldname))
		.map((f) => {
			const v = row[f.fieldname]
			if (v == null || v === '') return ''
			return ['Date', 'Datetime'].includes(f.fieldtype) ? formatDate(v) : String(v)
		})
		.filter(Boolean)
	return parts.length ? parts.join(' · ') : row.name
}

// ---- Data & pagination -----------------------------------------------------
const pageLength = ref(20)
const start = ref(0)
const rows = ref([])
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

// ---- Urutkan & saring (pola bottom-sheet, sama seperti Data Pengajuan) ------
const SORT_FIELDS = [
	{ key: 'modified', label: 'Terakhir Diubah' },
	{ key: 'employee_name', label: 'Nama Karyawan' },
	{ key: 'name', label: 'ID Karyawan' },
	{ key: 'date_of_joining', label: 'Tanggal Bergabung' },
]
const SARINGAN_KOSONG = { cari: '', status: [], department: [], branch: [] }
const JUDUL_PILIHAN = { status: 'Status', department: 'Departemen', branch: 'Cabang' }

const showSort = ref(false)
const showFilter = ref(false)
// Nama field yang sub-sheetnya sedang terbuka; '' berarti tertutup. Satu
// penanda untuk tiga daftar — isinya sama persis, hanya sumber pilihannya beda.
const showPilihan = ref('')

const sortField = ref('modified')
const sortDir = ref('desc')
const draftSortField = ref('modified')
const draftSortDir = ref('desc')

// `draft` diubah selama sheet terbuka; `terpakai` baru menyusul saat Terapkan,
// supaya menutup sheet tanpa menekan apa-apa tidak diam-diam mengubah daftar.
const terpakai = reactive({ ...SARINGAN_KOSONG, status: [], department: [], branch: [] })
const draft = reactive({ ...SARINGAN_KOSONG, status: [], department: [], branch: [] })

const opsiDepartemen = ref([])
const opsiCabang = ref([])
const pilihanAktif = computed(
	() =>
		({
			status: statusOptions.value.filter(Boolean),
			department: opsiDepartemen.value,
			branch: opsiCabang.value,
		})[showPilihan.value] || [],
)

const jumlahSaringan = computed(
	() =>
		(terpakai.cari ? 1 : 0) +
		terpakai.status.length +
		terpakai.department.length +
		terpakai.branch.length,
)

function ringkas(arr) {
	if (!arr.length) return ''
	return arr.length <= 2 ? arr.join(', ') : `${arr[0]} +${arr.length - 1}`
}

function pilihGanda(arr, nilai) {
	const i = arr.indexOf(nilai)
	if (i === -1) arr.push(nilai)
	else arr.splice(i, 1)
}

function openSort() {
	draftSortField.value = sortField.value
	draftSortDir.value = sortDir.value
	showSort.value = true
}
function applySort() {
	sortField.value = draftSortField.value
	sortDir.value = draftSortDir.value
	listPersistence.writePreferences({ sortField: sortField.value, sortDir: sortDir.value })
	showSort.value = false
	reload()
}
function openFilter() {
	Object.assign(draft, {
		cari: terpakai.cari,
		status: [...terpakai.status],
		department: [...terpakai.department],
		branch: [...terpakai.branch],
	})
	showFilter.value = true
}
function applyFilter() {
	Object.assign(terpakai, {
		cari: draft.cari.trim(),
		status: [...draft.status],
		department: [...draft.department],
		branch: [...draft.branch],
	})
	listPersistence.writeSession({ filters: terpakai })
	showFilter.value = false
	reload()
}
function clearFilter() {
	Object.assign(draft, { cari: '', status: [], department: [], branch: [] })
	Object.assign(terpakai, { cari: '', status: [], department: [], branch: [] })
	listPersistence.clearSession()
	showFilter.value = false
	reload()
}

// Saringan pilih-banyak jadi `in`; kata kunci jadi OR ke nama/ID/NIK, supaya
// satu kotak cari menjangkau ketiganya sekaligus.
function buildFilters() {
	const arr = []
	for (const f of ['status', 'department', 'branch']) {
		if (terpakai[f].length) arr.push([f, 'in', terpakai[f]])
	}
	return arr
}
function buildOrFilters() {
	const q = terpakai.cari
	if (!q) return []
	return [
		['employee_name', 'like', `%${q}%`],
		['name', 'like', `%${q}%`],
		['nik', 'like', `%${q}%`],
	]
}

const list = createResource({
	url: 'frappe.client.get_list',
	makeParams() {
		const params = {
			doctype: DOCTYPE,
			fields: JSON.stringify(listFields.value),
			order_by: `${sortField.value} ${sortDir.value}`,
			limit_start: start.value,
			limit_page_length: pageLength.value,
		}
		const f = buildFilters()
		if (f.length) params.filters = JSON.stringify(f)
		const orF = buildOrFilters()
		if (orF.length) params.or_filters = JSON.stringify(orF)
		return params
	},
	auto: false,
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === pageLength.value
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
}
function loadMore() {
	start.value += pageLength.value
	loading.value = true
	list.fetch()
}
// ---- Meta: field list view + opsi status -----------------------------------
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } },
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const meta = docs.find((x) => x.name === DOCTYPE) || docs[0]
		const fields = (meta && meta.fields) || []
		metaListFields.value = fields.filter((f) => f.in_list_view && !f.hidden)
		// Opsi filter status ikut opsi field `status` di doctype.
		const statusField = fields.find((f) => f.fieldname === 'status')
		if (statusField?.options) {
			statusOptions.value = ['', ...statusField.options.split('\n').filter(Boolean)]
		}
	} catch (e) {
		/* meta gagal → kartu tetap tampil dengan kerangka dasar */
	}
}

// Pilihan Departemen & Cabang diambil dari doctype tertautnya, bukan didaftar
// di kode — kalau HR menambah cabang baru, saringannya ikut tanpa ubah apa pun.
async function loadOpsiTautan() {
	const ambil = async (doctype) => {
		try {
			const r = await fetch(
				`/api/method/frappe.client.get_list?doctype=${encodeURIComponent(doctype)}` +
					`&fields=${encodeURIComponent(
						'["name"]',
					)}&limit_page_length=0&order_by=name%20asc`,
				{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } },
			)
			if (!r.ok) return []
			const j = await r.json()
			return (j.message || []).map((x) => x.name)
		} catch (e) {
			return [] // sub-sheetnya cuma jadi kosong, halaman tetap jalan
		}
	}
	opsiDepartemen.value = await ambil('Departemen')
	opsiCabang.value = await ambil('Cabang Perusahaan')
}

onMounted(async () => {
	await refreshCsrfToken()
	await Promise.all([loadMeta(), loadOpsiTautan()])
	const saved = listPersistence.readSession({ filters: SARINGAN_KOSONG }).filters
	saved.status = saved.status.filter((value) => statusOptions.value.includes(value))
	saved.department = saved.department.filter((value) => opsiDepartemen.value.includes(value))
	saved.branch = saved.branch.filter((value) => opsiCabang.value.includes(value))
	Object.assign(terpakai, saved)
	const prefs = listPersistence.readPreferences({ sortField: 'modified', sortDir: 'desc' })
	if (SORT_FIELDS.some((field) => field.key === prefs.sortField))
		sortField.value = prefs.sortField
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
	reload()
})
</script>

